import {tracePhoton,CRITICAL_IMPACT} from './blackhole-math.js';
export function setupPhotonTools(root,{getPath,getImpact,getProgress,setProgress,toggleFlight,dirty}){
 const console=root.querySelector('#panel-photon .experiment-console'),panel=document.createElement('div');panel.className='photon-tools';panel.innerHTML='<label>Ray simulation<select id="photon-mode"><option value="single">Single ray</option><option value="fan">Fan / 13 trajectories</option><option value="beam">Beam / 31 trajectories</option></select></label><label>Beam spread / Rs<input id="photon-spread" type="range" min=".01" max="1.2" step=".01" value=".18"></label><label>Wavelength / nm<input id="photon-wavelength" type="range" min="380" max="750" value="580"></label><label>Playback rate<select id="photon-rate"><option value=".25">0.25×</option><option value="1" selected>1×</option><option value="2">2×</option><option value="4">4×</option></select></label><label>Path progress<input id="photon-progress" type="range" min="0" max="1" step=".001" value="1"></label><div class="photon-buttons"><button id="photon-pause">Pause / resume</button><button id="photon-step">Step along path</button><button id="photon-scan">Scan capture boundary</button><button id="photon-export">Export ray bundle CSV ↧</button></div><label class="experiment-check"><input id="photon-straight" type="checkbox" checked> Straight-line reference</label><label class="experiment-check"><input id="photon-grid" type="checkbox" checked> Coordinate grid</label><output id="photon-bundle-summary" aria-live="polite"></output><p>Vacuum lensing is achromatic: all wavelengths follow the same geometric ray. Color is a wavelength label. Playback advances along the sampled path, not an observer clock.</p>';
 console.querySelector('.experiment-note').before(panel);const $=s=>panel.querySelector(s);let rays=[];
 function rebuild(){const count=$('#photon-mode').value==='single'?1:$('#photon-mode').value==='fan'?13:31,spread=+$('#photon-spread').value,b=getImpact();rays=Array.from({length:count},(_,i)=>count===1?getPath():tracePhoton(Math.max(.1,b+(i/(count-1)-.5)*spread)));const captured=rays.filter(p=>p.outcome==='captured').length,p=getPath(),a=p.points.at(-1),prior=p.points.at(-2),angle=Math.atan2(a[1]-prior[1],a[0]-prior[0])*180/Math.PI;$('#photon-bundle-summary').textContent=`${rays.length} rays · ${captured} captured · ${rays.length-captured} escaped / unresolved · outgoing direction ${p.outcome==='escaped'?angle.toFixed(1)+'°':'captured'} · finite integration boundary`;dirty();}
 for(const id of ['#photon-mode','#photon-spread'])$(id).oninput=rebuild;
 for(const id of ['#photon-wavelength','#photon-straight','#photon-grid'])$(id).oninput=dirty;
 $('#photon-progress').oninput=e=>setProgress(+e.target.value);$('#photon-pause').onclick=toggleFlight;$('#photon-step').onclick=()=>setProgress(Math.min(1,getProgress()+.015));$('#photon-scan').onclick=()=>{root.querySelector('#photon-impact').value=CRITICAL_IMPACT;$('#photon-mode').value='beam';$('#photon-spread').value=.12;root.querySelector('#photon-impact').dispatchEvent(new Event('input'));};
 $('#photon-export').onclick=()=>{const rows=['ray,impact_Rs,outcome,point_index,x_Rs,y_Rs,wavelength_nm'];rays.forEach((r,i)=>r.points.forEach((p,j)=>rows.push([i,r.impact,r.outcome,j,p[0],p[1],$('#photon-wavelength').value].join(','))));const u=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='ORBIT-photon-bundle.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);};
 function color(){const nm=+$('#photon-wavelength').value;return nm<450?'#aa8aff':nm<490?'#68acff':nm<530?'#7bdfcd':nm<590?'#f8d7a4':nm<650?'#ffa56b':'#ff706a';}
 return {rebuild,get speed(){return +$('#photon-rate').value},get grid(){return $('#photon-grid').checked},color,draw(c,{cx,cy,scale,progress,w,h}){if($('#photon-straight').checked){c.save();c.strokeStyle='#71869777';c.lineWidth=1;c.setLineDash([6,8]);c.beginPath();c.moveTo(0,cy-getImpact()*scale);c.lineTo(w,cy-getImpact()*scale);c.stroke();c.restore();}if(rays.length>1)rays.forEach((ray,i)=>{c.strokeStyle=ray.outcome==='captured'?'#de9e6465':'#79c9de65';c.lineWidth=1;c.beginPath();ray.points.slice(0,Math.max(2,Math.floor(ray.points.length*progress))).forEach(([x,y],j)=>j?c.lineTo(cx+x*scale,cy-y*scale):c.moveTo(cx+x*scale,cy-y*scale));c.stroke();});if(document.activeElement!==$('#photon-progress'))$('#photon-progress').value=progress;}};
}
